package sa.hulksa.player.data

import java.util.Base64
import okio.Buffer
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test
import sa.hulksa.player.model.ContentItem
import sa.hulksa.player.model.ContentType

/**
 * Executable differential corpus generated by the Android-12 AOSP org.json reference
 * (`android-12.0.0_r34`, commit e5e796352c04ed005d34367fbb737e7c3b300e00).
 *
 * Raw inputs are base64 strings and are never serialized through JSONObject before being passed
 * to the reader. Expected items are the reference mapper's complete ContentItem fields.
 */
class XtreamAndroidReferenceDifferentialTest {
    @Test
    fun matchesAndroid12ReferenceCorpus() {
        val stream = checkNotNull(javaClass.getResourceAsStream("/android12-reference-corpus.json"))
        val root = stream.bufferedReader(Charsets.UTF_8).use { JSONObject(it.readText()) }
        val cases = root.getJSONArray("cases")
        var comparisons = 0
        for (index in 0 until cases.length()) {
            val case = cases.getJSONObject(index)
            val caseId = case.getString("id")
            val type = ContentType.valueOf(case.getString("type"))
            val raw = String(Base64.getDecoder().decode(case.getString("raw_b64")), Charsets.UTF_8)
            val label = "$caseId/${type.name}"
            comparisons += 1
            if (case.getBoolean("accept")) {
                val actual = XtreamClient().parseCatalogItemsStreaming(
                    Buffer().writeUtf8(raw),
                    type,
                    PORTAL,
                )
                val expected = case.getJSONArray("items")
                assertEquals("$label item count", expected.length(), actual.size)
                for (itemIndex in 0 until expected.length()) {
                    assertItem(label, itemIndex, expected.getJSONObject(itemIndex), actual[itemIndex])
                }
            } else {
                assertThrows("$label expected reference rejection", XtreamJsonGuardException::class.java) {
                    XtreamClient().parseCatalogItemsStreaming(Buffer().writeUtf8(raw), type, PORTAL)
                }
            }
        }
        assertEquals(279, comparisons)
    }

    private fun assertItem(label: String, index: Int, expected: JSONObject, actual: ContentItem) {
        val prefix = "$label item=$index"
        assertEquals("$prefix id", expected.getInt("id"), actual.id)
        assertEquals("$prefix type", expected.getString("type"), actual.type.name)
        assertEquals("$prefix name", nullable(expected, "name"), actual.name)
        assertEquals("$prefix categoryId", nullable(expected, "categoryId"), actual.categoryId)
        assertEquals("$prefix posterUrl", nullable(expected, "posterUrl"), actual.posterUrl)
        assertEquals("$prefix rating", nullable(expected, "rating"), actual.rating)
        assertEquals("$prefix year", nullable(expected, "year"), actual.year)
        assertEquals("$prefix containerExtension", nullable(expected, "containerExtension"), actual.containerExtension)
        assertEquals("$prefix nowPlaying", nullable(expected, "nowPlaying"), actual.nowPlaying)
        assertEquals("$prefix plot", nullable(expected, "plot"), actual.plot)
        assertEquals("$prefix genre", nullable(expected, "genre"), actual.genre)
        assertEquals("$prefix backdropUrl", nullable(expected, "backdropUrl"), actual.backdropUrl)
        val added = if (!expected.has("addedAtEpochSeconds") || expected.isNull("addedAtEpochSeconds")) {
            null
        } else {
            expected.getLong("addedAtEpochSeconds")
        }
        assertEquals("$prefix addedAtEpochSeconds", added, actual.addedAtEpochSeconds)
    }

    private fun nullable(json: JSONObject, key: String): String? =
        if (!json.has(key) || json.isNull(key)) null else json.getString(key)

    private companion object {
        const val PORTAL = "https://portal.example/base"
    }
}
